1	/* ============================ Tự khám phá: điều phối chế độ bay dù lượn ============================
2	   Nối flight (mô hình), glider (dù), chase (camera) với vòng animate, phím và URL.
3	   `?explore=glider` bay thẳng; không tham số (hoặc `?test&chooser`) hiện màn chọn; Esc tải lại trang không còn tham số explore. Camera do explore.update đặt sau updateCamera. */
4	import * as THREE from 'three';
5	import { scene, camera, controls } from '../core/renderer';
6	import { cam, keys } from '../views/state';
7	import { exCreate, exStep, exInputFromKeys, type GliderState, type GliderInput } from './flight';
8	import { exBuildGlider, exPlaceGlider } from './glider';
9	import { exChase } from './chase';
10	import { exShowChooser } from './chooser';
11	import { exNight, exNightBind, exNightStep } from './nightShows';
12	import { exMulti } from './multi';
13	import { exWatchShow, exWatchHide, exWatchRender, exFlyNotice } from './multi/watch';
14	import { CONFIG } from '../config';
15	import type { SwingController } from '../bridges/song-han/SwingController';
16	
17	const _inp: GliderInput = { turn: 0, climb: 0, throttle: 0 };   // đầu vào tái dùng mỗi khung
18	
19	let glider: THREE.Group | null = null;
20	let state: GliderState | null = null;
21	let watching = false;   // đang xem người khác bay (hết chỗ hoặc vừa nhường chỗ): không có dù của mình, không đọc phím
22	let chased = false;     // camera đã bám người được xem lần nào chưa (lần đầu đặt thẳng, không trượt từ xa)
23	let readout = '';   // chữ đang hiện ở #exSpeed: chỉ ghi DOM khi đổi
24	
25	const active = () => cam.mode === 'glider' && state !== null;
26	const inGlider = () => active() || watching;   // Esc và giao diện bay áp cho cả chế độ xem
27	
28	/* Mỗi khung khi xem: dù người khác, nhãn, danh sách; camera bám dù đang xem (không có người thì giữ nguyên) */
29	function watchStep(dt: number): void {
30	  exMulti.update(dt, performance.now(), null);
31	  const st = exMulti.watchState();
32	  if (st) { exChase(camera, controls.target, st, dt, !chased); chased = true; }
33	  exNightStep(dt);
34	}
35	
36	/* Đổi phiên khi đang xem hoặc bay: vào bay, mất kết nối, bị thu hồi chỗ */
37	function onMultiChange(): void {
38	  const s = exMulti.session; if (!s) return;
39	  if (watching) {
40	    if (s.phase === 'flying') { explore.start(); return; }   // chấp nhận lời mời: cất cánh mới như bay thường
41	    if (s.phase === 'solo') { try { sessionStorage.setItem('exMpNotice', 'lost'); } catch { /* bộ nhớ bị chặn */ } explore.exit(); return; }   // màn chọn đọc cờ này và hiện exMpLost
42	    exWatchRender();
43	  } else if (active()) {
44	    if (s.phase === 'watching') { state = null; if (glider) glider.visible = false; explore.startWatching(true); return; }   // chỗ bị thu hồi: sang xem, camera giữ nguyên
45	    if (s.phase === 'solo' && s.notice === 'lost') exFlyNotice(s, 'exMpLost');   // vẫn bay, người khác đã biến mất
46	  }
47	}
48	
49	/* Đồng hồ tốc độ (km/h) và độ cao (m): chỉ số và đơn vị nên không cần dịch */
50	function exShowSpeed(): void {
51	  const t = `${Math.round(state!.speed * 3.6)} km/h · ${Math.round(state!.pos.y)} m`;
52	  if (t === readout) return;
53	  readout = t;
54	  const el = document.getElementById('exSpeed'); if (el) el.textContent = t;
55	}
56	
57	/* Một bước: mô phỏng, đặt dù, đặt camera bám */
58	function advance(dt: number, inp: GliderInput): void {
59	  exStep(state!, inp, dt);
60	  exPlaceGlider(glider!, state!);
61	  exChase(camera, controls.target, state!, dt);
62	  exShowSpeed();
63	  exNightStep(dt);
64	  exMulti.update(dt, performance.now(), state);   // dù người khác, nhãn tên, gửi vị trí (không làm gì khi bay một mình)
65	}
66	
67	export const explore = {
68	  active,
69	  nightShows: exNight,
70	  get state() { return state; },
71	  get glider() { return glider; },
72	  get watching() { return watching; },
73	  start(): void {
74	    if (watching) { watching = false; document.body.classList.remove('ex-watching'); exWatchHide(); }
75	    exMulti.onChange = onMultiChange;
76	    state = exCreate();
77	    const slot = exMulti.session ? exMulti.session.mySlot : -1;
78	    if (slot >= 0) state.pos.z += CONFIG.explore.multi.spawnSpread * (slot - 2);   // mỗi slot cất cánh lệch một đoạn để không chồng nhau
79	    if (!glider) glider = exBuildGlider();
80	    if (!glider.parent) scene.add(glider);
81	    glider.visible = true;
82	    cam.flight.then = null; cam.mode = 'glider'; controls.enabled = false;
83	    exPlaceGlider(glider, state);
84	    exChase(camera, controls.target, state, 0, true);
85	    exShowSpeed();
86	    document.body.classList.add('explore');
87	  },
88	  /* Chế độ xem: cam.mode = 'glider' nhưng không có state/dù của mình; carry = true khi vừa nhường chỗ (camera đang ở sau dù cũ) */
89	  startWatching(carry = false): void {
90	    const s = exMulti.session; if (!s) return;
91	    watching = true; chased = carry;
92	    keys.clear();
93	    cam.flight.then = null; cam.mode = 'glider'; controls.enabled = false;
94	    document.body.classList.add('explore', 'ex-watching');
95	    exMulti.onChange = onMultiChange;
96	    exWatchShow(s);
97	  },
98	  update(dt: number): void {
99	    if (watching) { watchStep(dt); return; }
100	    if (!active()) return;
101	    advance(dt, exInputFromKeys(keys, _inp));
102	  },
103	  /* Cho test: như update nhưng nhận đầu vào trực tiếp */
104	  step(dt: number, inp: GliderInput): void {
105	    if (active()) advance(dt, inp);
106	  },
107	  exit(): void {
108	    const u = new URL(location.href);
109	    u.searchParams.delete('explore'); u.searchParams.delete('chooser');
110	    if (u.href === location.href) location.reload();   // URL chỉ khác phần #ngôn-ngữ: replace chỉ là điều hướng fragment, không tải lại
111	    else location.replace(u.toString());
112	  },
113	};
114	
115	export function setupExplore(ctrl: SwingController): void {
116	  exNightBind(ctrl);
117	  window.addEventListener('keydown', (e) => {
118	    if (!inGlider()) return;
119	    if (e.key === 'Escape') { explore.exit(); return; }   // Esc thoát kể cả khi đang focus ô chọn
120	    if (watching) return;   // xem: không lái, không ghi phím
121	    if (e.ctrlKey || e.metaKey || e.altKey) return;   // phím tắt trình duyệt (Cmd+S...) không lái dù, tránh kẹt phím
122	    const t = e.target as HTMLElement | null;
123	    if (t && /^(SELECT|INPUT|TEXTAREA)$/.test(t.tagName)) return;   // phím trong ô chọn/nhập không lái dù
124	    const k = e.key.toLowerCase(); keys.add(k);
125	    if (k.startsWith('arrow')) e.preventDefault();
126	  });
127	  /* Chọn ngôn ngữ / chất lượng bằng chuột xong thì bỏ focus, nếu không mũi tên và WASD sau đó đổi cài đặt thay vì lái dù. Dùng Tab + bàn phím thì giữ nguyên. */
128	  for (const id of ['langSelect', 'qualitySel']) {
129	    const sel = document.getElementById(id); if (!sel) continue;
130	    let byMouse = false;
131	    sel.addEventListener('pointerdown', () => { byMouse = true; });
132	    sel.addEventListener('keydown', () => { byMouse = false; });
133	    sel.addEventListener('change', () => { if (byMouse && active()) sel.blur(); byMouse = false; });
134	  }
135	  const q = new URLSearchParams(location.search);
136	  exNight.enabled = !q.has('test');   // test bật tường minh qua __app.explore.nightShows
137	  if (q.has('test')) document.body.classList.add('ex-test');   // giữ HUD khi bay để test đo draw call
138	  document.getElementById('btnExExit')?.addEventListener('click', () => explore.exit());
139	  if (q.get('explore') === 'glider') { explore.start(); return; }
