275	  const badState = () => F.page.evaluate(() => { const i = document.getElementById('exMpInviteName'), b = document.getElementById('exMpInviteFly'); return { input: i.getClientRects().length > 0, v: i.value, off: b.disabled, joins: window.__joins, ls: localStorage.getItem('exMpName'), phase: window.__app.multi.session.phase }; });
276	  const waitBad = (n) => F.page.waitForFunction((k) => window.__joins === k && window.__app.multi.session.notice === 'nameBad', n, { timeout: 15000 }).catch(() => {});
277	  await F.page.fill('#exMpInviteName', 'fuck');
278	  await F.page.click('#exMpInviteFly');
279	  await waitBad(1); await frames(F.page, 3);
280	  const nb1 = await badState();
281	  check(`Tên bị từ chối: ô nhập hiện lại và trống, nút tắt, ${nb1.joins} join, chưa nhớ ("${nb1.ls}"), vẫn xem`, nb1.input && nb1.v === '' && nb1.off && nb1.joins === 1 && nb1.ls !== 'fuck' && nb1.phase === 'watching');
282	  await F.page.evaluate(() => { localStorage.setItem('exMpName', 'dit'); document.getElementById('exMpInviteName').dispatchEvent(new Event('input')); });
283	  await F.page.click('#exMpInviteFly');
284	  await waitBad(2); await frames(F.page, 3);
285	  const nb2 = await badState();
286	  check(`Tên đã nhớ bị từ chối: ô nhập hiện lại, tên bị xóa khỏi bộ nhớ ("${nb2.ls}"), ${nb2.joins} join`, nb2.input && nb2.v === '' && nb2.off && nb2.joins === 2 && !nb2.ls);
287	  await F.page.fill('#exMpInviteName', 'Mai');
288	  await F.page.dblclick('#exMpInviteFly');
289	  await F.page.waitForFunction(() => window.__app.explore.active() && window.__app.multi.session.phase === 'flying', null, { timeout: 60000 }).catch(() => {});
290	  await frames(F.page, 5);
291	  const fl = await F.page.evaluate(() => { const A = window.__app, g = A.explore.glider, R = A.multi.remotes; return { slot: A.multi.session.mySlot, joins: window.__joins, own: !!g && g.visible && !!g.parent && ![0, 1, 2, 3, 4].some((i) => R.group(i) === g), cls: document.body.classList.contains('ex-watching'), inv: document.getElementById('exMpInvite').getClientRects().length === 0 && document.getElementById('exMpWatch').getClientRects().length === 0, roster: document.getElementById('exMpRoster').innerText, ls: localStorage.getItem('exMpName'), st: !!A.explore.state }; });
292	  check(`Bấm mời khi có chỗ: bay được, slot ${fl.slot}, dù riêng của mình, giao diện xem gỡ, roster có Mai, ${fl.joins} lần join (2 bị từ chối + 1) dù bấm đúp, tên đã nhớ sau khi vào`, fl.slot >= 0 && fl.own && fl.st && !fl.cls && fl.inv && fl.roster.includes('Mai') && fl.joins === 3 && fl.ls === 'Mai');
293	
294	  // Mô phỏng máy chủ tắt bằng cách gọi onClose của kết nối (bắt tay đóng WebSocket với wrangler dev quá chậm để chờ)
295	  // Máy chủ tắt khi bay: vẫn bay, người khác biến mất, có exMpLost
296	  await F.page.evaluate(() => window.__app.multi.session.t.onClose());
297	  await F.page.waitForFunction(() => window.__app.multi.session.phase === 'solo', null, { timeout: 15000 }).catch(() => {});
298	  await frames(F.page, 5);
299	  const fl2 = await F.page.evaluate(() => { const A = window.__app, n = document.getElementById('exMpNotice'); return { active: A.explore.active(), others: [0, 1, 2, 3, 4].filter((i) => A.multi.remotes.slotState(i) || A.multi.remotes.group(i)).length, txt: n.innerText, shown: n.getClientRects().length > 0, roster: document.getElementById('exMpRoster').getClientRects().length > 0 }; });
300	  check(`Máy chủ tắt khi bay: vẫn bay, ${fl2.others} dù người khác, thông báo "${fl2.txt}"`, fl2.active && fl2.others === 0 && fl2.shown && /Mất kết nối/.test(fl2.txt) && !fl2.roster);
301	  check('Lỗi console của trang bay = 0', F.errors.length === 0);
302	  if (F.errors.length) console.log(F.errors.join('\n'));
303	  await F.page.close();   // đóng trang bay trước khi mở trang khác: SwiftShader dùng chung CPU
304	  addBot('Z');   // phòng lại đủ 5 (4 bot + Z) để trang tiếp theo vào thẳng chế độ xem
305	  await sleep(2500);
306	
307	  // Máy chủ tắt khi xem: quay về màn chọn và hiện exMpLost (phòng đủ 5)
308	  const L = await openApp(browser, URLW);
309	  await enterWatch(L.page);
310	  await Promise.all([L.page.waitForNavigation({ timeout: 90000 }).catch(() => null), L.page.evaluate(() => window.__app.multi.session.t.onClose())]);
311	  const flag = await L.page.evaluate(() => sessionStorage.getItem('exMpNotice'));
312	  check(`Máy chủ tắt khi xem: gọi thoát (trang tải lại), cờ sessionStorage "${flag}"`, flag === 'lost' && !/chooser/.test(L.page.url()));
313	  await L.page.goto(srv.url + '?chooser&test&multi=' + encodeURIComponent('ws://127.0.0.1:9/sky'), { waitUntil: 'load' });
314	  await L.page.waitForFunction(() => window.__app && document.getElementById('loading')?.classList.contains('done'), null, { timeout: 180000 });
315	  await L.page.waitForSelector('#chooser', { state: 'visible', timeout: 240000 });
316	  const lost = await L.page.evaluate(() => ({ txt: document.getElementById('exMpLostNote').innerText, shown: document.getElementById('exMpLostNote').getClientRects().length > 0, flag: sessionStorage.getItem('exMpNotice') }));
317	  check(`Màn chọn hiện "${lost.txt}" một lần (cờ đã xóa: ${lost.flag})`, lost.shown && /Mất kết nối/.test(lost.txt) && lost.flag === null);
318	  await L.page.close();
319	
320	  live.splice(0).forEach((b) => b.close());
321	} catch (e) {
322	  check('ngoại lệ: ' + e.message, false);
323	} finally {
324	  bots.forEach((b) => b.close());
325	  try { await browser?.close(); } catch { /* bỏ qua */ }
326	  try { srv?.close(); } catch { /* bỏ qua */ }
327	  stop();
328	  await sleep(1500);
329	}
330	console.log(problems.length ? `multi-check: LỖI (${problems.length}): ${problems.join('; ')}` : 'multi-check: đạt');
331	process.exit(problems.length ? 1 : 0);
