1	/* ===== Dù lượn nhiều người: điều phối phía khách =====
2	   Nối MultiSession (kết nối, phiên) với exRemotes (dù người khác), nhãn tên và danh sách người bay.
3	   Chỉ mở kết nối khi có người gọi begin(); ?test mà không có multi= thì url() rỗng nên không bao giờ mở WebSocket. */
4	import { camera } from '../../core/renderer';
5	import { CONFIG } from '../../config';
6	import { t, onChange as onLang } from '../../i18n';
7	import { exConnect } from './client';
8	import { MultiSession } from './session';
9	import { exRemotes } from './remote';
10	import { exLabelsUpdate, exLabelsClear } from './labels';
11	import type { GliderState } from '../flight';
12	
13	const M = CONFIG.explore.multi;
14	let session: MultiSession | null = null;
15	let sentAt = -1e9;
16	let rosterKey = '';
17	
18	/* Danh sách người bay ở góc màn hình: đầu "Đang bay n/5", mỗi người một dòng có chấm màu theo slot; dùng textContent */
19	function renderRoster(): void {
20	  const box = document.getElementById('exMpRoster');
21	  if (!box) return;
22	  const flyers = session ? session.flyers : [];
23	  const head = t('exMpFlying', { n: flyers.length });
24	  const key = flyers.map(f => f.slot + ':' + f.name).join('|') + '#' + (session ? session.mySlot : -1) + '#' + head;
25	  if (key === rosterKey) return;
26	  rosterKey = key;
27	  box.hidden = !session || session.phase === 'solo';
28	  box.textContent = '';
29	  const h = document.createElement('div'); h.className = 'ex-mp-head'; h.textContent = head; box.appendChild(h);
30	  for (const f of flyers) {
31	    const row = document.createElement('div'); row.className = 'ex-mp-row' + (session && f.slot === session.mySlot ? ' me' : '');
32	    const dot = document.createElement('i'); dot.style.background = M.colors[f.slot % M.colors.length];
33	    const nm = document.createElement('span'); nm.textContent = f.name;
34	    row.append(dot, nm); box.appendChild(row);
35	  }
36	}
