38	export const exMulti = {
39	  /* Địa chỉ máy chủ: ?multi= nếu có; ?test không có multi= thì rỗng (không mở mạng); còn lại cấu hình */
40	  url(): string {
41	    const q = new URLSearchParams(location.search);
42	    const u = q.get('multi');
43	    if (u !== null) return u;
44	    return q.has('test') ? '' : M.url;
45	  },
46	  get session(): MultiSession | null { return session; },
47	  onChange: (() => {}) as () => void,   // móc cho giao diện sảnh (Task 6) và test
48	
49	  /* Mở phiên; onReady gọi một lần khi có thông tin đầu tiên (sảnh hoặc ngoại tuyến). Trả false nếu không có địa chỉ */
50	  begin(onReady: () => void): boolean {
51	    const url = exMulti.url();
52	    if (!url || session) return false;
53	    const s = session = new MultiSession(() => exConnect(url, M.connectTimeoutMs));
54	    let ready = false;
55	    s.onPos = f => exRemotes.onPos(f, performance.now());
56	    s.onChange = () => {
57	      exRemotes.sync(s.flyers, s.mySlot);
58	      if (s.phase === 'solo') exLabelsClear();
59	      renderRoster();
60	      exMulti.onChange();
61	      if (!ready) { ready = true; onReady(); }
62	    };
63	    s.open();
64	    return true;
65	  },
66	
67	  /* Mỗi khung khi đang bay: dù người khác, nhãn, gửi vị trí sendHz lần/s */
68	  update(_dt: number, nowMs: number, state: GliderState | null): void {
69	    if (!session) return;
70	    exRemotes.update(nowMs);
71	    exLabelsUpdate(camera, exRemotes, nowMs);
72	    if (state && session.phase === 'flying' && nowMs - sentAt >= 1000 / M.sendHz) {
73	      sentAt = nowMs;
74	      const p = state.pos, r = (v: number) => Math.round(v * 10) / 10, a = (v: number) => Math.round(v * 1000) / 1000;
75	      session.sendPos(r(p.x), r(p.y), r(p.z), a(state.yaw), a(state.bank));
76	    }
77	  },
78	
79	  /* Trạng thái dù đang xem (khi hết chỗ, Task 6); null nếu không xem ai */
80	  watchState(): GliderState | null {
81	    return session && session.phase === 'watching' ? exRemotes.slotState(session.watched) : null;
82	  }
83	};
84	
85	onLang(() => { rosterKey = ''; renderRoster(); });
