37	function accept(): void {
38	  if (!session || session.phase !== 'watching' || pending) return;
39	  const input = $<HTMLInputElement>('exMpInviteName');
40	  const name = knownName() ?? exSanitizeName(input.value);
41	  if (name === null) return;
42	  pending = true; clearTimeout(pendingTimer);
43	  pendingTimer = window.setTimeout(() => { pending = false; exWatchRender(); }, CONFIG.explore.multi.pendingMs);
44	  session.join(name);   // join xóa notice cũ trước khi vẽ lại, nếu không nameBad cũ sẽ mở khóa nút ngay
45	  exWatchRender();
46	}
