content.content:
1	/* ===== Dù lượn nhiều người: giao diện chế độ xem và các thông báo =====
2	   #exMpWatch "Đang xem: tên", #exMpInvite (lời mời khi còn chỗ: ô tên nếu chưa có tên hợp lệ + nút vào bay), #exMpNotice (late / released / lost).
3	   Không điều khiển camera hay phiên: explore/index.ts gọi exWatchShow / exWatchRender / exWatchHide và tự xử lý chuyển pha.
4	   Mọi tên người khác chỉ ghi bằng textContent, bọc trong cặp cô lập hướng chữ để tên RTL không làm lệch câu. */
5	import { CONFIG } from '../../config';
6	import { t, onChange as onLang } from '../../i18n';
7	import { exSanitizeName } from './protocol';
8	import { exRemotes } from './remote';
9	import { loadName, saveName } from './lobby';
10	import type { MultiSession } from './session';
11	
12	const $ = <T extends HTMLElement>(id: string) => document.getElementById(id) as T;
13	
14	let session: MultiSession | null = null;
15	let bound = false;
16	let pending = false;       // đã bấm vào bay, chờ máy chủ trả lời: nút khóa để không gửi hai lần
17	let pendingTimer = 0;
18	let lateUntil = 0;         // mốc (ms) hết hạn hiện exMpLate
19	let lateTimer = 0;
20	let rejected: string | null = null;   // tên máy chủ vừa từ chối: không dùng lại, không nhớ
21	let noticeKey = '';        // khóa đang hiện ở #exMpNotice ('' = ẩn)
22	
23	/* Tên hợp lệ đã biết: tên đã dùng trong phiên, hoặc tên nhớ ở sảnh; bỏ tên máy chủ đã từ chối */
24	const okName = (n: string): string | null => { const v = exSanitizeName(n); return v !== null && v !== rejected ? v : null; };
25	const knownName = (): string | null => (session && okName(session.name)) || okName(loadName());
26	
27	/* Ghi/ẩn #exMpNotice (dùng cả khi đang bay: mất kết nối) */
28	export function exWatchNotice(key: string): void {
29	  noticeKey = key;
30	  const el = $('exMpNotice');
31	  el.textContent = key ? t(key) : '';
32	  el.hidden = !key;
33	}
34	
35	function unlock(): void { pending = false; clearTimeout(pendingTimer); }
36	
37	function accept(): void {
38	  if (!session || session.phase !== 'watching' || pending) return;
39	  const input = $<HTMLInputElement>('exMpInviteName');
40	  const name = knownName() ?? exSanitizeName(input.value);
41	  if (name === null) return;
42	  pending = true; clearTimeout(pendingTimer);
43	  pendingTimer = window.setTimeout(() => { pending = false; exWatchRender(); }, CONFIG.explore.multi.pendingMs);
44	  session.join(name);   // join xóa notice cũ trước khi vẽ lại, nếu không nameBad cũ sẽ mở khóa nút ngay
45	  exWatchRender();
46	}
47	
48	export function exWatchRender(): void {
49	  const s = session;
50	  if (!s || s.phase !== 'watching') return;
51	  /* Dòng "Đang xem" */
52	  const nm = s.watched >= 0 ? exRemotes.name(s.watched) : null;
53	  const w = $('exMpWatch');
54	  w.hidden = nm === null;
55	  w.textContent = nm === null ? '' : t('exMpWatching', { name: '\u2068' + nm + '\u2069' });
56	  /* Thông báo từ phiên: nút đã có trả lời thì mở khóa */
57	  if (pending && (s.notice === 'late' || s.notice === 'nameBad')) {
58	    unlock();
59	    if (s.notice === 'late') { lateUntil = performance.now() + CONFIG.explore.multi.lateMs; clearTimeout(lateTimer); lateTimer = window.setTimeout(exWatchRender, CONFIG.explore.multi.lateMs + 50); }
60	  }
61	  if (s.notice === 'nameBad' && s.name !== rejected) {   // tên bị từ chối: quên tên đó (cả bản đã nhớ), hiện lại ô nhập để gõ tên khác
62	    rejected = s.name;
63	    if (exSanitizeName(loadName()) === rejected) saveName('');
64	    $<HTMLInputElement>('exMpInviteName').value = '';
65	  }
66	  let key = '';
67	  if (s.notice === 'late') key = performance.now() < lateUntil ? 'exMpLate' : '';
68	  else if (s.notice === 'released') key = 'exMpReleased';
69	  else if (s.notice === 'nameBad') key = 'exMpNameBad';
70	  exWatchNotice(key);
71	  /* Lời mời */
72	  const inv = $('exMpInvite'), input = $<HTMLInputElement>('exMpInviteName'), btn = $<HTMLButtonElement>('exMpInviteFly');
73	  inv.hidden = !s.invite;
74	  const needName = knownName() === null;
75	  input.hidden = !needName;
76	  btn.disabled = pending || (needName && exSanitizeName(input.value) === null);
77	}
78	
79	/* Bắt đầu hiện giao diện xem cho phiên s */
80	export function exWatchShow(s: MultiSession): void {
81	  session = s; unlock(); lateUntil = 0; rejected = null;
82	  if (!bound) {
83	    bound = true;
84	    $('exMpInviteFly').addEventListener('click', accept);
85	    const input = $<HTMLInputElement>('exMpInviteName');
86	    input.addEventListener('input', exWatchRender);
87	    input.addEventListener('keydown', (e) => { if (e.key === 'Enter') { e.preventDefault(); accept(); } });   // Esc để lọt lên trình nghe chung (thoát)
88	    onLang(() => { if (session) { exWatchRender(); if (noticeKey && session.phase !== 'watching') exWatchNotice(noticeKey); } });
89	  }
90	  exWatchRender();
91	}
92	
93	/* Gỡ giao diện xem (vào bay, hoặc thoát) */
94	export function exWatchHide(): void {
95	  if (session && session.phase === 'flying') { const n = exSanitizeName(session.name); if (n !== null) saveName(n); }   // máy chủ đã nhận tên: bấy giờ mới nhớ
96	  session = null; unlock(); clearTimeout(lateTimer);
97	  $('exMpWatch').hidden = true; $('exMpInvite').hidden = true;
98	  exWatchNotice('');
99	}
100	
101	/* Khi đang bay: hiện một thông báo (mất kết nối); đổi ngôn ngữ thì dịch lại */
102	export function exFlyNotice(s: MultiSession, key: string): void {
103	  session = s;   // để onLang dịch lại
104	  exWatchNotice(key);
105	}
